#include "k501_aionarc/qh256_mapping.h"
int k501_aionarc_map_record_to_qh256(const k501_object_record_t*r,qh256_t*out){if(!r||!out)return -1;*out=qh256_unknown();qh256_set_cell(out,0u,QH_TRUE);qh256_set_cell(out,1u,r->readable?QH_TRUE:QH_FALSE);qh256_set_cell(out,2u,r->object_type==K501_OBJ_REGULAR_FILE?QH_TRUE:QH_FALSE);qh256_set_cell(out,3u,r->object_type==K501_OBJ_DIRECTORY?QH_TRUE:QH_FALSE);qh256_set_cell(out,4u,r->object_type==K501_OBJ_SYMLINK?QH_TRUE:QH_FALSE);qh256_set_cell(out,5u,r->object_type==K501_OBJ_OTHER?QH_TRUE:QH_FALSE);qh256_set_cell(out,6u,r->size_present?QH_TRUE:QH_FALSE);qh256_set_cell(out,7u,r->content_present?QH_TRUE:QH_FALSE);qh256_set_cell(out,8u,QH_TRUE);qh256_set_cell(out,9u,QH_TRUE);qh256_set_cell(out,10u,r->path_len>0u?QH_TRUE:QH_FALSE);qh256_set_cell(out,11u,r->root_id_len>0u?QH_TRUE:QH_FALSE);qh256_set_cell(out,12u,QH_TRUE);qh256_set_cell(out,13u,QH_TRUE);qh256_set_cell(out,14u,r->content_present?QH_TRUE:QH_FALSE);qh256_set_cell(out,15u,QH_TRUE);return 0;}
